contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // param unused for calls to c.refund but kept to follow template requiring params potential
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // no precondition on dummy
        // record balances before any interaction
        uint256 cBefore = address(c).balance;
        uint256 selfBefore = address(this).balance;

        // perform refund and capture whether it reverts
        bool refunded;
        // top-level try-catch as required
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            refunded = false;
        } else {
            refunded = true;
        }

        // record balances after
        uint256 cAfter = address(c).balance;
        uint256 selfAfter = address(this).balance;

        // General rule: either refund reverted and balances unchanged, or it succeeded and the decrease in c equals increase in this contract
        assert(
            (refunded == false && cAfter == cBefore && selfAfter == selfBefore)
            || (refunded == true && cBefore >= cAfter && selfAfter >= selfBefore && (cBefore - cAfter) == (selfAfter - selfBefore))
        );
    }

    // accept Ether when refund sends funds here
    receive() external payable {}
}

