// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 cBefore = address(c).balance;
        uint256 selfBefore = address(this).balance;
        bool refunded;
        try c.refund() {
            refunded = true;
        } catch {
            refunded = false;
        }
        uint256 cAfter = address(c).balance;
        uint256 selfAfter = address(this).balance;
        assertTrue((refunded == false && cAfter == cBefore && selfAfter == selfBefore)
            || (refunded == true && cBefore >= cAfter && selfAfter >= selfBefore && (cBefore - cAfter) == (selfAfter - selfBefore)));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
